(()=>{const out={};for(const kind of ['webgl','webgl2']){const g=new OffscreenCanvas(2,2).getContext(kind),e=kind==='webgl'?g.getExtension('ANGLE_instanced_arrays'):g,call=(n,...a)=>e[n+(kind==='webgl'?'ANGLE':'')](...a),r=out[kind]=[];for(const args of [[g.TRIANGLES,-1,3,0],[g.TRIANGLES,0,-1,0],[0,0,0,0],[12345,0,0,0],[g.TRIANGLES,0,3,-1],[g.TRIANGLES,0,3,0],[g.TRIANGLES,0,3,1]]){call('drawArraysInstanced',...args);r.push(g.getError())}}return out})()
